"""Build the compact R3-matched pickup addendum; physical tests remain pending."""
from pathlib import Path
import json,re
from reportlab.platypus import SimpleDocTemplate,Paragraph,Spacer,Table,TableStyle,PageBreak,Image
from reportlab.lib.styles import getSampleStyleSheet,ParagraphStyle
from reportlab.lib import colors
from reportlab.lib.pagesizes import A4
from reportlab.pdfbase import pdfmetrics
from reportlab.pdfbase.ttfonts import TTFont
from reportlab.lib.units import mm
P=Path(__file__).parent
for name,f in [('DV','DejaVuSans.ttf'),('DVB','DejaVuSans-Bold.ttf')]:pdfmetrics.registerFont(TTFont(name,'/usr/share/fonts/truetype/dejavu/'+f))
s=getSampleStyleSheet();s.add(ParagraphStyle(name='BodyRU',fontName='DV',fontSize=10.3,leading=14,spaceAfter=8));s.add(ParagraphStyle(name='HeadRU',fontName='DVB',fontSize=18,leading=23,spaceAfter=15));s.add(ParagraphStyle(name='SmallRU',fontName='DV',fontSize=8.4,leading=11,spaceAfter=5))
a=json.loads((P/'matched_math.json').read_text());fx=json.loads((P/'fixture_checks.json').read_text());flow=[];md=[]
def h(x):flow.append(Paragraph(x,s['HeadRU']));md.extend(['## '+x,''])
def tidy(x):
 x=re.sub(r'(?<=[а-яА-Я])(?=[0-9])|(?<=[0-9])(?=[а-яА-Я])',' ',str(x))
 x=re.sub(r'([≈≤≥±])',r' \1 ',x)
 return re.sub(' +',' ',x)
def p(x):
 x=tidy(x);flow.append(Paragraph(x,s['BodyRU']));md.extend([x.replace('<b>','**').replace('</b>','**'), ''])
def table(rows,widths):
 t=Table([[Paragraph(tidy(v),s['SmallRU'])for v in row]for row in rows],colWidths=widths,repeatRows=1)
 t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.HexColor('#e7eef3')),('VALIGN',(0,0),(-1,-1),'TOP'),('LINEBELOW',(0,0),(-1,0),.6,colors.grey),('BOTTOMPADDING',(0,0),(-1,-1),6),('TOPPADDING',(0,0),(-1,-1),6)]));flow.append(t);flow.append(Spacer(1,8));md.extend([' | '.join(map(str,r))for r in rows]);md.append('')
def page():flow.append(PageBreak());md.append('---\n')
h('Пассивная головка • согласование с R3')
p('Дополнение к основному руководству, 26.10.2026. Схема аксессуара P1 сохранена; входная нагрузка и чувствительность пересчитаны для R3. Это проект для сборки и низковольтной проверки, <b>не разрешение подключаться к зажиганию</b>.')
p('Внутри всего две детали: 10 нФ и 10 МОм параллельно между сигнальным диском и экраном. Диск чувствует электрическое поле снаружи исправного изолированного HT-провода к свече. Контакта с жилой нет. Для COP-катушки эта механика не выбрана.')
flow.append(Image(str(P/'figures/electrical.png'),width=176*mm,height=124.4*mm));md.append('Схема: kicad/passive-ht-pickup.pdf\n')
p('На схеме головки C1/R1 — <b>отдельные</b> детали аксессуара, не C1/R1 основной платы. SIG: диск, первые выводы C1/R1, центр кабеля/BNC. SHIELD: вторые выводы C1/R1, оплётка/BNC и отдельный провод GND_REF. SHIELD соединён с AGND прибора: гальванической развязки нет.')
p('Не добавлять терминатор 50 Ом. Не использовать прямой контакт с первичной или вторичной цепью. Номинал 100 В шунтирующего конденсатора не является пределом HV, рейтингом изоляции головки или диапазоном CH1.')
page();h('Детали и механическая сборка')
table([['Деталь','Исполнение'],['E1','Гладкий медный/латунный диск Ø10 мм, без острых краёв.'],['C1','10 нФ ±5%, MKP, 100 В: WIMA MKP2D021001B00JSSD, P5 мм, корпус примерно3 ×7,5 ×7,2 мм. Не заменять купленным PET фильтра без пересмотра.'],['R1','10 МОм ±1%, металлоплёночный THT, ≥0,25 Вт; пример MBB02070C1005FCT00.'],['Кабель/BNC','Фиксированная пара:1 м экранированного кабеля; пример Belden8259≈101 пФ/м; подходящий BNC-штекер и разгрузка натяжения.'],['GND_REF','От SHIELD у приборного конца: гибкий изолированный провод≈0,5 м/0,5 мм² и изолированный зажим.'],['Держатель','Полностью закрывает диск и пайку. Лицевая PTFE-пластина1 мм, напримерØ14 мм. Это повторяемая геометрия, не HV-рейтинг.']],[31*mm,145*mm])
flow.append(Image(str(P/'figures/mechanical.png'),width=176*mm,height=79*mm));md.append('Механический эскиз: figures/mechanical.svg (не масштабный HV-чертёж).\n')
p('1. Скруглить диск, припаять провод с обратной стороны. 2. За диском установить C1 и R1 с коротким участком3–5 мм, подключить кабель. 3. Очистить и высушить пайку; исключить контакт диска с экраном. 4. Закрепить кабель за оболочку. 5. Провести низковольтный тест до окончательного закрытия. 6. Закрыть металл и сделать повторяемую посадку без прокола/пережатия провода.')
p('Не экранировать заземлённой фольгой чувствительную сторону диска. Belden8259 рассчитан на −30…+75°C и радиус изгиба не менее48 мм при установке; это не жаростойкая автомобильная проводка.')
page();h('Первый тест — только низкое напряжение')
p('Высокое напряжение и автомобиль отсутствуют. Нужны генератор, исправный осциллограф, известный Ctest=10 нФ ±5%. Генератор подключают <b>через Ctest</b> к внутреннему SIG, возврат к SHIELD. Это проверка электрической сборки, не измерение реальной ёмкостной связи электрода.')
p('Без питания проверить непрерывность SIG/SHIELD и отсутствие замыкания между ними. После зарядного перехода мультиметр должен видеть около10 МОм; предел прибора должен позволять такое измерение. Измерить C1 отдельно:9,5–10,5 нФ.')
p('Проверить реальный перепад генератора <b>0→2 В целиком, не ±2 В</b>. Установка «для50 Ом» при высокоомном входе может удвоить амплитуду. Фронт0,1–10 мкс, измеренная скорость≤20 В/мкс, без выбросов; высокий уровень≥3 мс. Для отдельного установившегося фронта перед ним держать ноль≥2 с.')
table([['Подключение','Ранний пик CH1','Через2 мс после пика','Спад'],['Только осциллограф1 МОм','0,995 В','0,892 В','10,37%'],['R3 AC WIDE + щуп10 МОм','0,995 В','0,883 В','11,27%']],[61*mm,36*mm,45*mm,34*mm])
p('Это номинальная модель источника50 Ом, кабеля100 пФ и идеальной ступени. Реальный конечный фронт и погрешность приборов меняют цифры. Конечный перебор C±5%, R±1%, щуп0–30 пФ и Rs0/50/1050 Ом даёт пики0,941–1,045 В и спад9,77–10,98% /10,63–11,94% соответственно; это не сертифицированные пределы неизвестного прибора.')
p('Сначала проверять отдельно с входом осциллографа1 МОм. С R3 повторять только после собственной низковольтной приёмки платы, используя контрольный щуп10 МОм на CH1. Дополнительный вход1 МОм параллельно R3 почти вдвое меняет нагрузку и не соответствует второй строке. После проверки удалить Ctest и закрыть головку без наружного контакта SIG.')
p('Для AC-запуска следовать основному руководству R3: источник отсоединён, питание выключено, CH1 на AGND, сброс C9 в DC≥2 с, S2=WIDE; S1=AC ещё без питания; включить общую шину, держать CH1 на AGND≥10 с и проверить устойчивый ноль. Не включать DC+SENSITIVE.')
page();h('Что измеряет и чего не подтверждает головка')
p(f"Нагрузка R3 в AC≈{a['R3_AC_input_ohm']/1e6:.6f} МОм. ACS gain≈{a['R3_ACS_gain']:.8f}; номинально {a['R3_ACS_input_mV_per_code12']:.3f} мВ/12-bit код и {a['R3_ACS_input_mV_per_saved10_step']:.3f} мВ/сохранённый10-bit шаг. Это чувствительность CH1, не перевод в киловольты.")
p(f"В условном примере Cs=1 пФ, Cш=10 нФ, кабель100 пФ и Rразр=10 МОм спад за2 мс≈{a['droop2ms_pct']:.2f}% с учётом AC-связи платы. Полоса R3≈17,84 кГц дополнительно сглаживает быстрый пик. Поэтому самодельная пассивная головка не обещает точный пик пробоя, наклон линии горения или диагноз катушки.")
p('Cs зависит от изоляции, посадки, соседних проводов и металла. Диаметр диска не определяет её однозначно. Для отдельного перепада приближённо K=Cs/(Cs+Cш+Cкабеля), но предыстория заряда может увеличить следующую экскурсию. Номинальный коэффициент и отсутствие обрезания после фильтра не доказывают допустимость быстрых пиков на CH1.')
p('<b>Автомобильный этап пока не выполнен.</b> До него отдельно проверяют реальную головку подходящим защищённым автомобильным измерительным входом при полностью отсоединённом R3: обе полярности пиков, нагрузку≈1 МОм, полосу, предысторию, посадку и изменчивость режима. Нужен запас на неопределённость. Если подходящей контрольной системы нет, пределы головки не подтверждены.')
p('Только чистый, сухой, неповреждённый провод с исправной двойной изоляцией; установка/снятие при выключенном и защищённом от случайного запуска двигателе. Общая земля головки/R3/USB/контрольного прибора проверяется заранее. PE не отключать; батарейное питание ноутбука само по себе не доказывает безопасную развязку. Кабель удалять от горячих и движущихся частей. Повреждённая изоляция, доступный металл или неизвестная земля — остановка, не повод добавить изоленту.')
p('Для первого подтверждённого сигнала — AC WIDE. SENSITIVE только после независимой проверки обеих полярностей на разъёме и предыстории. Для формы слабого сигнала полезен100k/12bit при подтверждённой конфигурации. Записать номер головки/кабеля, физический режим, Fs/retained_bits, пики CH1, шум, повторяемость посадки и фактически выполненные проверки.')
p('Основа: неизменённый P1 commit47c22d6; обновлены только согласование и численные примеры R3. Первичные ссылки: sources/SOURCES.md общего пакета (Pico, WIMA, Belden). Полные расчётные предпосылки: matched_math.json и fixture_checks.json. Испытания изоляции, зажигания и автомобиля не выполнены.')
def footer(c,doc):
 c.setFont('DV',8);c.setFillColor(colors.grey);c.drawString(17*mm,11*mm,'R3 • Пассивная головка • Проект, не HV/CAT-допуск');c.drawRightString(193*mm,11*mm,str(doc.page))
